export function relatedBlogs(article, limit = 3) {
  return [...blogs.filter(b => b.slug !== article.slug && b.topic === article.topic),
    ...blogs.filter(b => b.slug !== article.slug && b.topic !== article.topic && b.solution === article.solution)].slice(0, limit);
}
export function readingMinutes(article) {
  const words = [article.answer, ...article.sections.flat(), ...article.checklist, article.question, article.response].join(' ').split(/\s+/).length;
  return Math.max(2, Math.ceil(words / 180));
}
